import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import {
  Card,
  Container,
  Row,
  Col,
  Form,
  Button,
} from "react-bootstrap";
import "chartist/dist/chartist.min.css";

//============= STYLE ===============
const themeStyle = `
  .chart-scroll {
    overflow-x: auto;
    overflow-y: hidden;
  }

  /* ปรับส่วนหัวให้เป็นสีม่วงไล่เฉดตามรูป (Purple Gradient) */
  .history-header {
    background: linear-gradient(87deg, #5e72e4 0, #825ee4 100%) !important;
    border-radius: 8px 8px 0 0 !important;
    padding: 20px !important;
  }

  .history-header .card-title {
    color: white !important;
    margin: 0 !important;
    font-weight: bold;
    font-size: 1.25rem;
  }

  /* ตกแต่งช่องเลือก (Select) ให้ดูสะอาดตาและโค้งมน */
  .form-select {
    border-radius: 12px !important; 
    padding: 10px 18px !important;
    border: 1px solid #e9ecef !important;
    background-color: #ffffff !important;
    box-shadow: 0 1px 3px rgba(0, 0, 0, .08) !important;
    font-size: 14px !important;
    color: #525f7f !important;
  }

  /* ปรับสี Label ให้เป็นสีม่วงเข้ม/น้ำเงิน ตามสไตล์ในรูป */
  .form-label {
    font-weight: 700;
    color: #5e72e4;
    text-transform: uppercase;
    font-size: 0.75rem;
    letter-spacing: .025em;
    margin-bottom: 8px;
  }

  /* ตกแต่ง Card ให้มีเงาฟุ้งๆ (Soft Shadow) เหมือนในรูป */
  .card {
    border: none !important;
    box-shadow: 0 0 2rem 0 rgba(136, 152, 170, .15) !important;
    margin-bottom: 30px !important;
    border-radius: 0.75rem !important;
    background-color: #ffffff !important;
  }

  /* สไตล์เพิ่มเติมสำหรับปุ่มหรือ Badge ที่เป็นสีม่วง (ถ้ามี) */
  .btn-primary, .badge-primary {
    background-color: #5e72e4 !important;
    border-color: #5e72e4 !important;
    border-radius: 10px !important;
  }

  .bg-transparent {
    background-color: transparent !important;
  }
`;

const SLOT_INTERVAL = 30;

const generateTimeSlots = (startHour = 7, endHour = 22, interval = SLOT_INTERVAL) => {
  const slots = [];
  const startMin = startHour * 60;
  const endMin = endHour * 60;

  for (let m = startMin; m <= endMin; m += interval) {
    const h = Math.floor(m / 60);
    const min = m % 60;
    slots.push(
      `${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`
    );
  }
  return slots;
};

const normalizeTo30MinSlots = (labels, values, startTime, endTime) => {
  const slots = generateTimeSlots(
    parseInt(startTime.split(":")[0]),
    parseInt(endTime.split(":")[0]),
    30
  );

  const slotMap = {};
  const countMap = {};
  slots.forEach(s => {
    slotMap[s] = 0;
    countMap[s] = 0;
  });

  labels.forEach((time, idx) => {
    const [h, m] = time.split(":").map(Number);
    const roundedMin = m < 30 ? "00" : "30";
    const slotKey = `${h.toString().padStart(2, "0")}:${roundedMin}`;
    if (slotMap[slotKey] !== undefined) {
      slotMap[slotKey] += values[idx];
      countMap[slotKey] += 1;
    }
  });

  return {
      labels: slots,
      series: [
        slots.map(s =>
          countMap[s] > 0 ? Math.round(slotMap[s] / countMap[s]) : 0
        )
      ]
    };
};

const timeToMinutes = (time) => {
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
};

function History() {
  const currentYearCE = new Date().getFullYear();
  const currentYearBE = currentYearCE + 543;

  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, "0"));
  const [selectedYearBE, setSelectedYearBE] = useState((currentYearCE + 543).toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [chartState, setChartState] = useState({ labels: [], series: [[]] });
  const [loading, setLoading] = useState(false);

  const monthsThai = [
    { val: "01", name: "มกราคม" }, 
    { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, 
    { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, 
    { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, 
    { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, 
    { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, 
    { val: "12", name: "ธันวาคม" }
  ];

  const yearsBE = Array.from({ length: 5 }, (_, i) => (currentYearBE - i).toString());
  const daysArray = Array.from({ length: 31 }, (_, i) => (i + 1).toString());
  const timeOptions = [];
  for (let h = 7; h <= 22; h++) {
    timeOptions.push(`${h.toString().padStart(2, "0")}:00`);
  }

  const handleSearch = async () => {
    setLoading(true);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, "0")}`;
    try {
      const res = await fetch(`http://localhost:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`);
      const result = await res.json();
      if (result && result.labels && result.series) {
        const normalized = normalizeTo30MinSlots(
          result.labels,
          result.series[0],
          startTime,
          endTime
        );

        setChartState(normalized);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    handleSearch();
  }, [selectedDay, selectedMonth, selectedYearBE, startTime, endTime, cameraId]);

  const barChartOptions = {
    height: "400px",
    axisX: { showGrid: false, offset: 60 },
    axisY: {
      low: 0,
      high: 50,          // 👈 ล็อกค่าสูงสุด
      onlyInteger: true
    },
    fullWidth: true
  };

  const drawBarLabels = (data) => {
    if (data.type === "bar") {
      const color = data.value.y > 20 ? "#f5365c" : "#2dce89"; 
      data.element.attr({ style: `stroke: ${color}; stroke-width: 30px;` });
      data.group.elem("text", {
        x: data.x2,
        y: data.y2 - 15,
        style: "font-size:14px;fill:#000;font-weight:bold;text-anchor:middle",
      }).text(data.value.y);
    }
  };

  return (
    <Container fluid className="py-4">
      <style>{themeStyle}</style>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header className="history-header">
              <Card.Title as="h4">ค้นหาข้อมูลย้อนหลัง</Card.Title>
            </Card.Header>
            <Card.Body className="px-4 py-4">
              <Row className="align-items-end g-3">
                <Col lg="3" md="4">
                  <Form.Group>
                    <Form.Label className="form-label">สถานีจุดจอด</Form.Label>
                    <Form.Select className="w-100" value={cameraId} onChange={e => setCameraId(e.target.value)}>
                      <option value="CAM01">วิศวะ</option>
                      <option value="CAM02">วิทยาศาสตร์</option>
                      <option value="CAM03">ศิลปศาสตร์</option>
                      <option value="CAM04">PKY</option>
                    </Form.Select>
                  </Form.Group>
                </Col>
                <Col lg="4" md="8">
                  <Form.Label className="form-label">เลือกวันที่</Form.Label>
                  <div className="d-flex gap-2">
                    <Form.Select className="flex-grow-1" value={selectedDay} onChange={e => setSelectedDay(e.target.value)}>
                      {daysArray.map(d => <option key={d} value={d}>{d}</option>)}
                    </Form.Select>
                    <Form.Select className="flex-grow-1" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                      {monthsThai.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                    </Form.Select>
                    <Form.Select className="flex-grow-1" value={selectedYearBE} onChange={e => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map(y => <option key={y} value={y}>{y}</option>)}
                    </Form.Select>
                  </div>
                </Col>
                <Col lg="5" md="12">
                  <Form.Label className="form-label">เลือกช่วงเวลา</Form.Label>
                  <div className="d-flex gap-2 align-items-center">
                    <Form.Select className="flex-grow-1" value={startTime} onChange={e => setStartTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Select>
                    <span className="text-muted px-1 small">ถึง</span>
                    <Form.Select className="flex-grow-1" value={endTime} onChange={e => setEndTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Select>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {chartState.labels.length > 0 && (
        <Row>
          <Col md="12">
            <Card>
              <Card.Header className="bg-transparent border-0 pt-4 px-4">
                <h6 className="text-uppercase text-muted ls-1 mb-1">Overview</h6>
                <h2 className="mb-0 h4 font-weight-bold">กราฟย้อนหลัง : {cameraId}</h2>
              </Card.Header>
              <Card.Body className="px-4">
                <div className="chart-scroll">
                  <div style={{ width: Math.max(chartState.labels.length * 70, 600), height: "400px" }}>
                    <ChartistGraph
                      data={{ labels: chartState.labels, series: chartState.series }}
                      type="Bar"
                      options={barChartOptions}
                      listener={{ draw: drawBarLabels }}
                    />
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
